def component(name:str,weight:float,fn:Callable[[],tuple[bool,str]])->dict[str,Any]:
 try: passed,detail=fn()
 except Exception as exc: passed,detail=False,f"{type(exc).__name__}: {exc}"
 return {"name":name,"weight":weight,"passed":bool(passed),"detail":str(detail)}

def sha(path:Path)->str: return hashlib.sha256(path.read_bytes()).hexdigest()
def rows(text:str):
 reader=csv.DictReader(io.StringIO(text),delimiter="\t"); return list(reader.fieldnames or []),list(reader)
def emit(fields:list[str],records:list[dict[str,str]])->str:
 stream=io.StringIO(); writer=csv.DictWriter(stream,fieldnames=fields,delimiter="\t",lineterminator="\n"); writer.writeheader(); writer.writerows(records); return stream.getvalue()
def numeq(a:str,b:str)->bool:
 if a=="NA" or b=="NA": return a==b
 try: x,y=float(a),float(b)
 except (TypeError,ValueError): return False
 return math.isfinite(x) and math.isfinite(y) and math.isclose(x,y,rel_tol=REL_TOL,abs_tol=ABS_TOL)
def inteq(a:str,b:str)->bool:
 if a=="NA" or b=="NA": return a==b
 try: x,y=float(a),float(b)
 except (TypeError,ValueError): return False
 return math.isfinite(x) and math.isfinite(y) and x.is_integer() and y.is_integer() and int(x)==int(y)
def booleq(a:str,b:str)->bool:
 if a=="NA" or b=="NA": return a==b
 parsed={"true":True,"false":False}
 x,y=parsed.get(a.strip().casefold()),parsed.get(b.strip().casefold())
 return x is not None and y is not None and x==y

def compare(actual_text:str,expected_text:str,filename:str,columns:list[str]|None=None)->tuple[bool,str]:
 if not actual_text: return False,f"{filename} unavailable"
 af,ar=rows(actual_text); ef,er=rows(expected_text); spec=TABLE_SPECS[filename]; key=spec["key"]
 if not set(ef).issubset(af): return False,f"missing columns {sorted(set(ef)-set(af))}"
 def index(items):
  out={}; duplicate=False
  for row in items:
   ident=tuple(row.get(k,"") for k in key); duplicate|=ident in out; out[ident]=row
  return out,duplicate
 a,dup=index(ar); e,_=index(er)
 if dup: return False,"duplicate row identity"
 if set(a)!=set(e): return False,f"row identities differ: actual={len(a)} expected={len(e)}"
 checked=columns if columns is not None else [c for c in ef if c not in key]; numeric=set(spec["numeric"]); integer=set(spec["integer"]); boolean=set(spec["boolean"])
 for ident,want in e.items():
  got=a[ident]
  for col in checked:
   if col not in got: return False,f"missing checked column {col}"
   ok=inteq(got[col],want[col]) if col in integer else numeq(got[col],want[col]) if col in numeric else booleq(got[col],want[col]) if col in boolean else got[col]==want[col]
   if not ok: return False,f"{ident} {col}: {got[col]!r} != {want[col]!r}"
 return True,f"{filename} matches {len(e)} complete row(s)"

def run_project(project:Path,config_text:str,inputs:dict[str,str]):
 with tempfile.TemporaryDirectory(prefix="joint-screen-check-") as td:
  root=Path(td); fixture=root/"fixture"; out=root/"out"; fixture.mkdir()
  for name,text in inputs.items(): (fixture/name).write_text(text,encoding="utf-8")
  config=root/"analysis_config.json"; config.write_text(config_text,encoding="utf-8")
  cp=subprocess.run([sys.executable,str(project/"scripts/reproduce.py"),"--config",str(config),"--data-dir",str(fixture),"--output-dir",str(out),"--require-match"],cwd=project,env={**os.environ,"PYTHONDONTWRITEBYTECODE":"1"},text=True,capture_output=True,timeout=60)
  if cp.returncode: raise RuntimeError(cp.stderr[-1600:] or cp.stdout[-1600:])
  tables={n:(out/n).read_text() for n in TABLE_SPECS}; receipt=json.loads((out/"reproduction.json").read_text())
  return tables,receipt

def main()->int:
 p=argparse.ArgumentParser(); p.add_argument("--output",required=True,type=Path); p.add_argument("--result-file",required=True,type=Path); args=p.parse_args()
 output=args.output.resolve(); project=output/"code/ntab"; comps=[]
 try: answer=json.loads((output/"answer.json").read_text())
 except Exception: answer={}
 for name,key in [("diagnosis_bug_type","bug_type"),("diagnosis_earliest_fault","earliest_fault"),("diagnosis_repair_scope","repair_scope"),("diagnosis_bias_direction","bias_direction"),("diagnosis_fixed","fixed")]:
  comps.append(component(name,1.5,lambda key=key:(answer.get(key)==PAYLOAD["answer"][key],f"{key} scientific commitment")))

 def fixture_integrity():
  base=project/"fixtures/public"; wrong=[n for n,d in PAYLOAD["fixture_hashes"].items() if not (base/n).is_file() or sha(base/n)!=d]
  return not wrong,"mounted fixture bytes preserved" if not wrong else f"changed fixture files: {wrong}"
 comps.append(component("submitted_fixture_integrity",4.0,fixture_integrity))

 mounted=Path("/home/agent/data"); mounted=mounted if mounted.is_dir() else Path(__file__).resolve().parents[1]/"environment/data"
 config_text=(mounted/"analysis_config.json").read_text(); names=tuple(PAYLOAD["fixture_hashes"]); public_dir=mounted/"broken_project/fixtures/public"
 inputs={}
 try:
  inputs={n:(public_dir/n).read_text() for n in names}; fresh,fresh_receipt=run_project(project,config_text,inputs)
 except Exception: fresh,fresh_receipt={}, {}
 expected=PAYLOAD["public_expected"]
 checks=[
  ("fresh_complete_compound_novelty","compound_novelty.tsv",None,12.0),
  ("fresh_complete_pair_population","assay_pair_audit.tsv",["target_a","target_b","pair_status","mirroring_flag","policy_applies"],8.0),
  ("fresh_pair_overlap","assay_pair_audit.tsv",["n_shared_compounds"],4.0),
  ("fresh_pair_correlation","assay_pair_audit.tsv",["pearson_r","r2"],5.0),
  ("fresh_pair_target_identity","assay_pair_audit.tsv",["target_identity"],4.0),
  ("fresh_assay_base_statistics","assay_inventory.tsv",["n_input_rows","n_tier_rows","n_unique_compounds","experimental_sd","base_eligibility_status"],5.0),
  ("fresh_joint_assay_eligibility","assay_inventory.tsv",["target_mirroring_pair_count","mirroring_policy_applies","eligibility_status","retained"],8.0),
  ("fresh_document_evidence","document_retention.tsv",None,5.0),
  ("fresh_performance","assay_performance.tsv",None,4.0),
  ("fresh_split_summary","summary.tsv",None,5.0),
 ]
 for name,filename,cols,weight in checks: comps.append(component(name,weight,lambda filename=filename,cols=cols:compare(fresh.get(filename,""),expected[filename],filename,cols)))

 for case in HIDDEN_CASES:
  case_inputs=dict(inputs); case_inputs.update(case["inputs"]); mutation=case["mutation"]
  if mutation["kind"]=="reverse_rows":
   for filename in ("activities.tsv","assay_documents.tsv","compound_fingerprints.tsv","target_identity.tsv"):
    fields,records=rows(case_inputs[filename]); case_inputs[filename]=emit(fields,list(reversed(records)))
  elif mutation["kind"]=="negative_r":
   fields,records=rows(case_inputs["activities.tsv"]); assay_a,assay_b=mutation["assay_a"],mutation["assay_b"]
   left={r["ligand_chembl_id"] for r in records if r["assay_chembl_id"]==assay_a and r["pchembl_relation"]=="=" and r["pchembl_value_filled"] not in ("","NA")}
   shared=sorted(left & {r["ligand_chembl_id"] for r in records if r["assay_chembl_id"]==assay_b and r["pchembl_relation"]=="=" and r["pchembl_value_filled"] not in ("","NA")})
   values={lig:next(r["pchembl_value_filled"] for r in records if r["assay_chembl_id"]==assay_b and r["ligand_chembl_id"]==lig and r["pchembl_relation"]=="=") for lig in shared}; reversed_values=dict(zip(shared,reversed([values[x] for x in shared])))
   for row in records:
    if row["assay_chembl_id"]==assay_b and row["ligand_chembl_id"] in reversed_values and row["pchembl_relation"]=="=": row["pchembl_value_filled"]=reversed_values[row["ligand_chembl_id"]]
   case_inputs["activities.tsv"]=emit(fields,records)
  try: actual,_=run_project(project,config_text,case_inputs)
  except Exception: actual={}
  def casecheck(actual=actual,case=case):
   for filename,cols in case["checks"].items():
    if filename=="all":
     for table in TABLE_SPECS:
      ok,detail=compare(actual.get(table,""),case["expected"][table],table)
      if not ok:return ok,detail
     return True,"all generated tables invariant"
    use=None if cols=="all" else cols; ok,detail=compare(actual.get(filename,""),case["expected"][filename],filename,use)
    if not ok:return ok,detail
   return True,"perturbation-owned fields and declared invariants match"
  comps.append(component("hidden_"+case["name"],5.0,casecheck))

 submitted={}
 for filename in TABLE_SPECS:
  try: submitted[filename]=(output/filename).read_text()
  except Exception: submitted[filename]=""
 for filename in TABLE_SPECS: comps.append(component("regenerated_"+filename.replace(".tsv",""),1.0,lambda filename=filename:compare(submitted.get(filename,""),fresh.get(filename,""),filename)))
 def receipt_check():
  try: actual=json.loads((output/"reproduction.json").read_text())
  except Exception:return False,"receipt unavailable"
  if not isinstance(actual.get("status"),str) or actual["status"]!=fresh_receipt.get("status"):return False,"receipt status differs"
  if type(actual.get("release_match")) is not bool or actual["release_match"]!=fresh_receipt.get("release_match"):return False,"receipt release_match differs"
  if type(actual.get("difference_count")) is not int:return False,"receipt difference_count is not an integer"
  differences=actual.get("differences")
  if not isinstance(differences,list) or not all(isinstance(item,str) for item in differences):return False,"receipt differences is not a string array"
  if actual["difference_count"]!=len(differences) or differences!=fresh_receipt.get("differences"):return False,"receipt differences differ"
  output_files=actual.get("output_files"); expected_files=fresh_receipt.get("output_files")
  if not isinstance(output_files,list) or not all(isinstance(item,str) for item in output_files):return False,"receipt output_files is not a string array"
  if len(output_files)!=len(set(output_files)) or sorted(output_files)!=sorted(expected_files):return False,"receipt output_files differs"
  return True,"receipt agrees with fresh replay"
 comps.append(component("regenerated_receipt",1.0,receipt_check))
 total=sum(float(c["weight"]) for c in comps); earned=sum(float(c["weight"]) for c in comps if c["passed"])
 result={"score":earned/total if total else 0.0,"earned_weight":earned,"total_weight":total,"components":comps}
 args.result_file.parent.mkdir(parents=True,exist_ok=True); args.result_file.write_text(json.dumps(result,indent=2)+"\n"); return 0
